package com.hospital.service.impl;
import com.hospital.entity.Room; import com.hospital.entity.RoomAllocation; import com.hospital.entity.Patient; import com.hospital.repository.PatientRepository; import com.hospital.repository.RoomAllocationRepository; import com.hospital.repository.RoomRepository; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.InjectMocks; import org.mockito.Mock; import org.mockito.junit.jupiter.MockitoExtension; import java.time.LocalDate; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class RoomAllocationServiceImplTest {
 @Mock RoomAllocationRepository allocations; @Mock RoomRepository rooms; @Mock PatientRepository patients; @InjectMocks RoomAllocationServiceImpl service;
 private Room room(){Room r=new Room();r.setRoomId(2);r.setTotalBeds(3);r.setAvailableBeds(3);r.setRoomStatus("AVAILABLE");return r;}
 private RoomAllocation allocation(){RoomAllocation a=new RoomAllocation();a.setPatientId(5);a.setRoomId(2);a.setBedNumber(1);a.setAdmissionDate(LocalDate.of(2026,11,21));return a;}
 @Test void allocatesBedAndRecalculatesCount(){Room r=room();RoomAllocation a=allocation();when(rooms.lockById(2)).thenReturn(Optional.of(r));when(patients.lockById(5)).thenReturn(Optional.of(new Patient()));when(allocations.existsByRoomIdAndBedNumberAndReleaseDateIsNull(2,1)).thenReturn(false);when(allocations.existsByPatientIdAndReleaseDateIsNull(5)).thenReturn(false);when(allocations.save(a)).thenReturn(a);when(allocations.countByRoomIdAndReleaseDateIsNull(2)).thenReturn(1L);assertEquals(a,service.create(a));assertEquals(2,r.getAvailableBeds());verify(rooms).save(r);}
 @Test void rejectsOccupiedBed(){RoomAllocation a=allocation();when(rooms.lockById(2)).thenReturn(Optional.of(room()));when(patients.lockById(5)).thenReturn(Optional.of(new Patient()));when(allocations.existsByRoomIdAndBedNumberAndReleaseDateIsNull(2,1)).thenReturn(true);assertThrows(IllegalArgumentException.class,()->service.create(a));}
 @Test void rejectsPatientAlreadyAdmitted(){RoomAllocation a=allocation();when(rooms.lockById(2)).thenReturn(Optional.of(room()));when(patients.lockById(5)).thenReturn(Optional.of(new Patient()));when(allocations.existsByRoomIdAndBedNumberAndReleaseDateIsNull(2,1)).thenReturn(false);when(allocations.existsByPatientIdAndReleaseDateIsNull(5)).thenReturn(true);assertThrows(IllegalArgumentException.class,()->service.create(a));}
 @Test void rejectsBedNumberBeyondRoomCapacity(){RoomAllocation a=allocation();a.setBedNumber(4);when(rooms.lockById(2)).thenReturn(Optional.of(room()));when(patients.lockById(5)).thenReturn(Optional.of(new Patient()));assertThrows(IllegalArgumentException.class,()->service.create(a));}
 @Test void activeAllocationCannotBeDeleted(){RoomAllocation a=allocation();when(allocations.lockById(10)).thenReturn(Optional.of(a));assertThrows(IllegalArgumentException.class,()->service.delete(10));}
 @Test void releaseUpdatesRoomBedCount(){RoomAllocation current=allocation();Room r=room();when(allocations.lockById(11)).thenReturn(Optional.of(current));when(rooms.lockById(2)).thenReturn(Optional.of(r));when(allocations.save(current)).thenReturn(current);when(allocations.countByRoomIdAndReleaseDateIsNull(2)).thenReturn(0L);RoomAllocation request=allocation();request.setReleaseDate(LocalDate.of(2026,11,22));assertEquals(request.getReleaseDate(),service.update(11,request).getReleaseDate());assertEquals(3,r.getAvailableBeds());}
}
